#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long binPow(long long base, long long exp, long long mod) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    long long l;
    cin >> n >> k >> l;
    l %= MOD;

    vector<vector<long long>> cnk(2004, vector<long long>(2004, 0));
    vector<long long> fact(4004, 0);
    vector<long long> reverse(4004, 0);
    vector<long long> deg2(2004, 0);

    cnk[0][0] = 1;
    for (int i = 1; i < 2004; i++) {
        cnk[0][i] = 1;
        for (int j = 1; j <= i; j++) {
            cnk[j][i] = (cnk[j - 1][i - 1] + cnk[j][i - 1]) % MOD;
        }
    }

    fact[0] = 1;
    deg2[0] = 1;
    for (int i = 1; i < 4004; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
        deg2[i] = (deg2[i - 1] * 2) % MOD;
    }

    reverse[1] = 1;
    for (int i = 3; i < 4004; i += 2) {
        reverse[i] = binPow(fact[i], MOD - 2, MOD);
    }

    long long answer = 0;
    for (int i = k; i <= n; i++) {
        long long tmp = 0;
        for (int s = 0, c = 1; s <= n - i; s++, c = -c) {
            long long a = 1;
            a = (a * cnk[s][n - i]) % MOD;
            a = (a * deg2[s]) % MOD;
            a = (a * fact[s + i]) % MOD;
            a = (a * fact[s + i]) % MOD;
            a = (a * reverse[2 * (s + i) + 1]) % MOD;
            tmp = (tmp + a * c) % MOD;
        }
        long long b = (tmp * deg2[i]) % MOD;
        b = (b * cnk[i][n]) % MOD;
        answer = (answer + b) % MOD;
    }
    answer = (answer * l) % MOD;
    cout << (answer >= 0 ? answer : answer + MOD) << "\n";
    return 0;
}

